// Embeds playlists/*.m3u8 into js/builtin.js so the app ships with them (no XHR needed).
const fs = require('fs'), path = require('path');
const dir = path.join(__dirname, '..', 'playlists');
const names = { 'polska_ace_stream2.m3u8': ['builtin-polska-ace', 'Polska (Ace Stream)'] };
const list = fs.readdirSync(dir).filter(f => /\.m3u8?$/.test(f)).map(f => ({
  id: (names[f] || ['builtin-' + f])[0], name: (names[f] || [0, f])[1], builtin: true,
  text: fs.readFileSync(path.join(dir, f), 'utf8')
}));
fs.writeFileSync(path.join(__dirname, '..', 'js', 'builtin.js'),
  '/* generated by tools/build-playlist.js – do not edit */\nvar BUILTIN_PLAYLISTS = ' + JSON.stringify(list) + ';\n');
console.log('built-in playlists:', list.map(l => l.name + ' (' + (l.text.match(/#EXTINF/g) || []).length + ')').join(', '));
